
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_airy_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_airy", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.140615889323558e+00, -4.056946718242186e+00, -3.939816679487917e+00, -3.777812855910176e+00, -3.557644882278574e+00, -3.266013551803064e+00, -2.894035371038264e+00, -2.445134887486787e+00, -1.943400951789302e+00, -1.431203474333207e+00, -9.626500337384524e-01, -6.759791893084597e-01, -5.867839674037525e-01, -4.718556024955012e-01, -3.355508566656019e-01, -2.126082694982118e-01, -1.250253509491884e-01, -6.923152305234442e-02, -4.037489276616830e-02, -2.806957090066035e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


